import type { Metadata } from "next";
import ThemeIcon from "./ThemeIcon";
import { AgencyButton, BlogCard, PlanCard, ProjectCard, SectionHeading, ServiceCard, TeamCard, TestimonialCard } from "./DashboardComponents";
import "./signal-agency.css";

export const metadata: Metadata = { title: "Signal Agency — Digital Growth Studio", description: "A high-contrast digital agency theme built with Coordiation components, icons, and utilities." };

const team = [
  ["Ana Mahesa", "Strategy Director", "team-ana.jpg"], ["Raka Putra", "Product Lead", "team-raka.jpg"],
  ["Nadia Kirana", "Creative Director", "team-nadia.jpg"], ["Bima Arwana", "Engineering Lead", "team-bima.jpg"],
];

export default function SignalAgencyPreview() {
  return <main className="signal-agency co-overflow-hidden" id="top">
    <header className="sa-header co-flex co-items-center co-justify-between"><a className="sa-logo co-flex co-items-center" href="#top"><span>Signal</span><i /></a><nav className="co-flex co-items-center" aria-label="Signal Agency navigation"><a href="#about">About</a><a href="#services">Services</a><a href="#work">Projects</a><a href="#team">Team</a><a href="#journal">Journal</a></nav><AgencyButton href="#contact">Start a project</AgencyButton><details className="sa-mobile-menu"><summary aria-label="Open navigation"><ThemeIcon name="hamburger-menu" size={22} tone="accent" /></summary><div className="co-flex co-flex-col"><a href="#about">About</a><a href="#services">Services</a><a href="#work">Projects</a><a href="#team">Team</a><a href="#journal">Journal</a><a href="#contact">Start a project</a></div></details></header>

    <section className="sa-hero"><div className="sa-hero-title"><p className="sa-kicker co-flex co-items-center"><i className="motion-safe:co-animate-pulse motion-reduce:co-animate-none" />Digital growth partner</p><h1>Grow your digital<br /><em>signal.</em></h1><p>Strategy, design, and technology for ambitious teams building the next useful thing.</p><AgencyButton href="#work">Explore our work</AgencyButton></div><aside className="sa-hero-left co-grid"><div><ThemeIcon name="target" size={24} tone="accent" /><strong>50k+</strong><span>Qualified actions created</span></div><div><ThemeIcon name="graph-new-up" size={24} tone="accent" /><strong>4.8×</strong><span>Average growth impact</span></div></aside><figure className="sa-hero-image co-relative co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover" src="/themes/signal-agency/hero-team.jpg" alt="Creative agency team collaborating around laptops" /><figcaption className="co-absolute co-flex co-items-center co-justify-between"><span>Jakarta · Singapore · Remote</span><b>EST. 2019</b></figcaption></figure><aside className="sa-hero-right co-flex co-flex-col"><a className="sa-play co-inline-flex co-items-center co-justify-center" href="#showreel" aria-label="Play agency showreel"><ThemeIcon name="play-circle" size={34} tone="accent" /></a><div><strong>25k</strong><span>Campaign outcomes tracked</span></div><p>Trusted by product teams across finance, mobility, health, and culture.</p></aside></section>

    <section className="sa-about co-grid" id="about"><div className="sa-about-collage co-grid"><img className="co-w-full co-h-full co-object-cover" src="/themes/signal-agency/about-team.jpg" alt="Creative team working together in a studio" /><div className="co-flex co-flex-col co-justify-between"><span>24/7 support</span><strong>One team from first signal to launch.</strong><ThemeIcon name="users-group-rounded" size={25} tone="accent" /></div></div><div><p className="sa-kicker co-flex co-items-center"><i />About us</p><h2>We’re a creative<br />digital studio.</h2><p>Signal brings brand strategy, product design, growth thinking, and development into one close working team. The result is clearer decisions and experiences people return to.</p><div className="sa-about-principles co-grid"><article><ThemeIcon name="target" size={23} tone="accent" /><h3>Our vision</h3><p>Make useful digital products feel unmistakably human.</p></article><article><ThemeIcon name="shield-check" size={23} tone="accent" /><h3>Our mission</h3><p>Turn complexity into a strong, measurable customer experience.</p></article></div><AgencyButton href="#services" outline>Discover Signal</AgencyButton></div></section>

    <section className="sa-services" id="services"><SectionHeading eyebrow="Services" title={<>Creative systems<br />that move business.</>} copy="We combine the disciplines needed to take an idea from strategy to a responsive, launch-ready experience." action={<AgencyButton href="#contact" outline>See all services</AgencyButton>} /><div className="sa-service-grid co-grid"><ServiceCard index="01" icon="monitor" title="Web experiences" copy="High-performing marketing sites shaped around a clear customer journey." image="/themes/signal-agency/project-product.jpg" /><ServiceCard index="02" icon="palette" title="Digital identity" copy="Flexible visual systems that make every product touchpoint recognizable." image="/themes/signal-agency/project-strategy.jpg" /><ServiceCard index="03" icon="code" title="Product interfaces" copy="Useful UX, robust UI patterns, and responsive frontend implementation." image="/themes/signal-agency/project-interface.jpg" /></div></section>

    <section className="sa-showreel co-relative co-flex co-items-center co-justify-center co-text-center" id="showreel"><img className="co-absolute co-w-full co-h-full co-object-cover" src="/themes/signal-agency/blog-meeting.jpg" alt="Team reviewing a digital strategy together" /><div className="co-absolute" /><div className="co-relative"><p className="sa-kicker co-flex co-items-center co-justify-center"><i />Connect</p><h2>Want to work<br />with us?</h2><a className="sa-play co-inline-flex co-items-center co-justify-center" href="#contact" aria-label="Contact Signal Agency"><ThemeIcon name="play-circle" size={42} tone="accent" /></a></div><footer className="co-absolute co-grid"><a className="co-flex co-items-center" href="tel:+62215550184"><ThemeIcon name="phone" size={18} tone="accent" /><span>Call for inquiry<small>+62 21 555 0184</small></span></a><a className="co-flex co-items-center" href="mailto:hello@signal.example"><ThemeIcon name="letter" size={18} tone="accent" /><span>Email for inquiry<small>hello@signal.example</small></span></a><AgencyButton href="#contact">Contact now</AgencyButton></footer></section>

    <section className="sa-benefits"><SectionHeading eyebrow="Why Signal" title={<>Crafting experiences.<br />Delivering success.</>} copy="Fast collaboration, direct access to specialists, and decisions that stay connected to the outcome." /><div className="sa-benefit-layout co-grid"><div className="sa-benefit-stack co-grid"><article><ThemeIcon name="graph-new-up" size={24} tone="accent" /><h3>Fast, reliable service</h3><p>Short feedback loops and visible delivery milestones.</p></article><article><ThemeIcon name="shield-check" size={24} tone="accent" /><h3>Ongoing support</h3><p>A familiar team remains available after launch.</p></article></div><figure className="co-relative co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover" src="/themes/signal-agency/team-ana.jpg" alt="Signal Agency strategy director" /><figcaption className="co-absolute">A senior partner stays close to every project.</figcaption></figure><div className="sa-benefit-stack co-grid"><article><ThemeIcon name="users-group-rounded" size={24} tone="accent" /><h3>One integrated team</h3><p>Strategy, design, and engineering work from one brief.</p></article><article><ThemeIcon name="target" size={24} tone="accent" /><h3>Measurable outcomes</h3><p>Success measures are agreed before the first screen.</p></article></div></div></section>

    <section className="sa-work" id="work"><SectionHeading eyebrow="Projects" title={<>Work that ignites<br />business growth.</>} copy="A selection of brand, product, and campaign systems built around a real opportunity." action={<AgencyButton href="#contact" outline>More projects</AgencyButton>} /><div className="sa-project-grid co-grid"><ProjectCard wide category="Brand strategy" title="Voltase mobility platform" image="/themes/signal-agency/project-strategy.jpg" /><ProjectCard category="Product design" title="Nadi health companion" image="/themes/signal-agency/project-interface.jpg" /><ProjectCard category="Digital experience" title="Teras workspace" image="/themes/signal-agency/project-product.jpg" /></div><div className="sa-logo-row co-grid">{["NUSAPULSE","METRO LAB","SAGARA","NADI","KARYA GRID"].map((brand)=><span key={brand}>{brand}</span>)}</div></section>

    <section className="sa-pricing"><SectionHeading eyebrow="Pricing" title={<>Choose your<br />best plan.</>} copy="Clear starting points for different stages of growth. Every engagement is adapted after discovery." /><div className="sa-plan-grid co-grid"><PlanCard name="Foundation" price="129" /><PlanCard name="Growth" price="150" featured /><PlanCard name="Scale" price="199" /></div></section>

    <section className="sa-stats co-relative co-grid"><img className="co-absolute co-w-full co-h-full co-object-cover" src="/themes/signal-agency/about-team.jpg" alt="" /><div className="co-absolute" />{[["10k+","Useful actions"],["8k+","Qualified leads"],["98%","Client retention"],["25+","Years combined"]].map(([value,label])=><article className="co-relative co-text-center" key={label}><strong>{value}</strong><span>{label}</span></article>)}</section>

    <section className="sa-team" id="team"><div className="sa-team-intro"><p className="sa-kicker co-flex co-items-center"><i />Our team</p><h2>Small senior team.<br />Serious range.</h2><p>Meet the people who turn strategy into useful interfaces, scalable systems, and measurable growth.</p><AgencyButton href="#contact" outline>Meet everyone</AgencyButton></div><div className="sa-team-grid co-grid">{team.map(([name,role,image])=><TeamCard key={name} name={name} role={role} image={`/themes/signal-agency/${image}`} />)}</div></section>

    <section className="sa-testimonials"><SectionHeading eyebrow="Testimonials" title={<>What clients<br />say about Signal.</>} copy="Long-term partnerships built on clear thinking, responsive collaboration, and work that performs." /><div className="sa-quote-grid co-grid"><TestimonialCard quote="They turned a scattered brief into a product story our entire company could finally believe in." name="Julian Tan" role="Founder, Nadi" /><TestimonialCard quote="Signal moved quickly without making the work feel rushed. Every decision had a reason and a measure." name="Mira Halim" role="VP Growth, Voltase" /><TestimonialCard quote="The system is still easy for our internal team to use, which is the clearest sign they built it properly." name="David Putra" role="Director, Teras" /></div></section>

    <section className="sa-journal" id="journal"><SectionHeading eyebrow="From the studio" title={<>A glance at our<br />latest thinking.</>} copy="Practical notes on useful products, strong identities, and building growth systems that last." action={<AgencyButton href="#contact" outline>View journal</AgencyButton>} /><div className="sa-blog-grid co-grid"><BlogCard image="/themes/signal-agency/blog-meeting.jpg" date="Aug 24, 2026" category="Strategy" title="Managing the way your team measures success" /><BlogCard image="/themes/signal-agency/project-product.jpg" date="Aug 12, 2026" category="Design systems" title="Why clarity makes digital experiences feel faster" /><BlogCard image="/themes/signal-agency/project-interface.jpg" date="Jul 28, 2026" category="Product" title="Creating interfaces people can learn without friction" /></div></section>

    <section className="sa-contact co-grid co-items-center" id="contact"><div><p className="sa-kicker co-flex co-items-center"><i />Next project</p><h2>Want to work<br />with Signal?</h2><p>Tell us what you are building and where the opportunity feels stuck.</p><div className="co-flex co-items-center"><AgencyButton href="mailto:hello@signal.example">Start the conversation</AgencyButton><a className="sa-contact-play co-inline-flex co-items-center" href="#showreel"><ThemeIcon name="play-circle" size={35} tone="accent" />Watch showreel</a></div></div><img className="co-w-full co-h-full co-object-cover" src="/themes/signal-agency/hero-team.jpg" alt="Signal Agency team" /></section>

    <footer className="sa-footer"><div className="sa-footer-grid co-grid"><div><a className="sa-logo co-flex co-items-center" href="#top"><span>Signal</span><i /></a><p>Independent digital studio helping ambitious teams build clear, useful, and measurable experiences.</p></div><div><strong>Quick links</strong><a href="#about">About</a><a href="#services">Services</a><a href="#work">Projects</a><a href="#journal">Journal</a></div><div><strong>Services</strong><a href="#services">Brand strategy</a><a href="#services">Product design</a><a href="#services">Web development</a><a href="#services">Growth systems</a></div><div><strong>Contact</strong><a href="mailto:hello@signal.example">hello@signal.example</a><a href="tel:+62215550184">+62 21 555 0184</a><span>Jakarta · Singapore</span></div></div><div className="sa-footer-bottom co-flex co-items-center co-justify-between"><span>© 2026 Coordiation. All rights reserved.</span><div className="co-flex co-items-center"><a href="#top">Back to top</a><ThemeIcon name="arrow-to-top-right" size={14} tone="accent" /></div></div></footer>
  </main>;
}

.signal-agency { --sa-ink:#090a09; --sa-panel:#121311; --sa-line:#30332d; --sa-muted:#9da095; --sa-lime:#c6ff27; width:100%; min-height:100vh; background:var(--sa-ink); color:#f2f4ec; font-family:Arial,Helvetica,sans-serif; font-size:15px; line-height:1.5; }
.signal-agency *,.signal-agency *::before,.signal-agency *::after { box-sizing:border-box; }
.signal-agency h1,.signal-agency h2,.signal-agency h3,.signal-agency p,.signal-agency figure,.signal-agency blockquote { margin:0; }
.signal-agency img { display:block; max-width:100%; }
.signal-agency a { color:inherit; text-decoration:none; }
:where(.signal-agency.co-overflow-hidden,.signal-agency .co-overflow-hidden) { overflow:hidden; }
:where(.signal-agency .co-flex) { display:flex; }
:where(.signal-agency .co-inline-flex) { display:inline-flex; }
:where(.signal-agency .co-grid) { display:grid; }
:where(.signal-agency .co-items-center) { align-items:center; }
:where(.signal-agency .co-items-end) { align-items:flex-end; }
:where(.signal-agency .co-justify-between) { justify-content:space-between; }
:where(.signal-agency .co-justify-center) { justify-content:center; }
:where(.signal-agency .co-flex-col) { flex-direction:column; }
:where(.signal-agency .co-relative) { position:relative; }
:where(.signal-agency .co-absolute) { position:absolute; }
:where(.signal-agency .co-w-full) { width:100%; }
:where(.signal-agency .co-h-full) { height:100%; }
:where(.signal-agency .co-object-cover) { object-fit:cover; }
:where(.signal-agency .co-text-center) { text-align:center; }
:where(.signal-agency .co-transition) { transition-property:color,background-color,border-color,box-shadow,opacity,transform; }
:where(.signal-agency .co-duration-300) { transition-duration:300ms; }
:where(.signal-agency .co-duration-500) { transition-duration:500ms; }
:where(.signal-agency .co-ease-out) { transition-timing-function:cubic-bezier(.16,1,.3,1); }
@keyframes sa-pulse { 0%,100% { opacity:1; } 50% { opacity:.45; } }
@media (prefers-reduced-motion:no-preference) { :where(.signal-agency .motion-safe\:co-animate-pulse) { animation:sa-pulse 2s cubic-bezier(.4,0,.6,1) infinite; } }
.sa-icon { display:block; object-fit:contain; }
.sa-icon-light { filter:brightness(0) invert(1); }.sa-icon-dark { filter:brightness(0); }.sa-icon-accent { filter:brightness(0) saturate(100%) invert(87%) sepia(88%) saturate(1345%) hue-rotate(28deg) brightness(108%) contrast(106%); }
.sa-header { width:min(1180px,calc(100% - 40px)); min-height:78px; margin:0 auto; gap:24px; border-bottom:1px solid var(--sa-line); }
.sa-logo { gap:7px; font-size:22px; font-weight:900; letter-spacing:-.06em; }.sa-logo i { width:8px; height:8px; display:block; border-radius:50%; background:var(--sa-lime); box-shadow:0 0 20px rgb(198 255 39 / .65); }
.sa-header nav { gap:28px; font-size:11px; font-weight:700; }.sa-header nav a { color:#bfc2b7; transition:color .2s ease; }.sa-header nav a:hover { color:var(--sa-lime); }
.sa-button { min-width:160px; min-height:48px; padding:0 7px 0 18px; gap:20px; border:1px solid var(--sa-lime); border-radius:99px; background:var(--sa-lime); color:#080908!important; font-size:11px; font-weight:800; }
.sa-button > span { width:34px; height:34px; border-radius:50%; background:#0a0b09; }.sa-button:hover { transform:translateY(-3px); box-shadow:0 10px 30px rgb(198 255 39 / .15); }
.sa-button.is-outline { background:transparent; color:#f4f5ef!important; }.sa-button.is-outline > span { background:var(--sa-lime); }
.sa-mobile-menu { display:none; position:relative; }.sa-mobile-menu summary { list-style:none; cursor:pointer; }.sa-mobile-menu summary::-webkit-details-marker { display:none; }.sa-mobile-menu > div { width:230px; padding:18px; position:absolute; z-index:30; right:0; top:34px; gap:15px; border:1px solid var(--sa-line); background:#0c0d0b; box-shadow:0 16px 38px #000; font-size:12px; }.sa-mobile-menu a:last-child { color:var(--sa-lime); }
.sa-kicker { gap:9px; margin:0 0 18px; color:#b7baaE; font-size:9px; font-weight:800; text-transform:uppercase; letter-spacing:.17em; }.sa-kicker i { width:6px; height:6px; display:block; border-radius:50%; background:var(--sa-lime); }
.sa-hero { width:min(1180px,calc(100% - 40px)); min-height:760px; margin:0 auto; padding:86px 0 72px; display:grid; grid-template-columns:230px minmax(0,1fr) 230px; grid-template-rows:auto 1fr; gap:24px; position:relative; }
.sa-hero-title { grid-column:1/-1; width:74%; margin:0 auto; position:relative; z-index:3; text-align:center; }.sa-hero-title .sa-kicker { justify-content:center; }.sa-hero h1 { margin:0; font-size:clamp(58px,7.1vw,108px); line-height:.82; letter-spacing:-.075em; }.sa-hero h1 em { color:var(--sa-lime); font-style:normal; }.sa-hero-title > p:not(.sa-kicker) { max-width:520px; margin:28px auto 30px; color:var(--sa-muted); font-size:14px; line-height:1.7; }.sa-hero-title .sa-button { margin:auto; }
.sa-hero-left { align-self:center; gap:18px; }.sa-hero-left > div,.sa-hero-right > div { padding:20px; display:grid; gap:8px; border:1px solid var(--sa-line); background:#0d0e0c; }.sa-hero-left strong,.sa-hero-right strong { font-size:34px; letter-spacing:-.06em; }.sa-hero-left span,.sa-hero-right span { color:var(--sa-muted); font-size:9px; line-height:1.4; }
.sa-hero-image { min-height:400px; border:1px solid var(--sa-line); }.sa-hero-image::after { content:""; position:absolute; inset:0; background:linear-gradient(180deg,transparent 55%,rgb(0 0 0 / .76)); pointer-events:none; }.sa-hero-image img { filter:saturate(.8) contrast(1.05); }.sa-hero-image figcaption { z-index:1; right:20px; bottom:17px; left:20px; color:#e7e9df; font-size:9px; }.sa-hero-image figcaption b { color:var(--sa-lime); }
.sa-hero-right { align-self:center; gap:18px; }.sa-hero-right .sa-play { width:102px; height:102px; margin:auto; border:1px solid var(--sa-line); border-radius:50%; }.sa-play { transition:transform .25s ease,border-color .25s ease; }.sa-play:hover { transform:scale(1.07); border-color:var(--sa-lime); }.sa-hero-right p { margin:0; color:var(--sa-muted); font-size:10px; line-height:1.7; text-align:center; }
.sa-about { width:min(1180px,calc(100% - 40px)); margin:0 auto; padding:120px 0; grid-template-columns:1fr 1fr; gap:80px; align-items:center; }
.sa-about-collage { grid-template-columns:1fr .7fr; min-height:560px; gap:14px; }.sa-about-collage > img { object-position:48% center; }.sa-about-collage > div { padding:25px; border:1px solid var(--sa-line); background:var(--sa-panel); }.sa-about-collage > div span { color:var(--sa-lime); font-size:10px; font-weight:800; text-transform:uppercase; }.sa-about-collage > div strong { font-size:29px; line-height:1; letter-spacing:-.05em; }
.sa-about h2,.sa-section-heading h2,.sa-team-intro h2,.sa-contact h2 { margin:0; font-size:clamp(48px,5.2vw,78px); line-height:.9; letter-spacing:-.065em; }.sa-about > div:last-child > p:not(.sa-kicker) { max-width:540px; margin:28px 0; color:var(--sa-muted); font-size:14px; line-height:1.75; }
.sa-about-principles { margin:32px 0; grid-template-columns:1fr 1fr; border:1px solid var(--sa-line); }.sa-about-principles article { min-height:190px; padding:24px; }.sa-about-principles article+article { border-left:1px solid var(--sa-line); }.sa-about-principles h3 { margin:38px 0 8px; font-size:19px; }.sa-about-principles p { margin:0; color:var(--sa-muted); font-size:10px; line-height:1.65; }
.sa-services,.sa-work,.sa-pricing,.sa-testimonials,.sa-journal { padding:120px max(20px,calc((100vw - 1180px)/2)); background:var(--sa-panel); }
.sa-section-heading { grid-template-columns:minmax(0,1.15fr) minmax(220px,.7fr) auto; gap:42px; margin-bottom:58px; }.sa-section-heading > * { min-width:0; }.sa-section-heading > p { margin:0; color:var(--sa-muted); font-size:12px; line-height:1.7; }.sa-section-heading > span { display:block; }
.sa-service-grid { grid-template-columns:repeat(3,minmax(0,1fr)); gap:14px; }.sa-service { min-height:510px; padding:25px; border:1px solid var(--sa-line); background:#0c0d0b; }.sa-service > div span { color:var(--sa-lime); font-family:monospace; font-size:11px; }.sa-service h3 { margin:56px 0 12px; font-size:26px; letter-spacing:-.04em; }.sa-service > p { margin:0 0 26px; color:var(--sa-muted); font-size:10px; line-height:1.65; }.sa-service figure { min-height:250px; margin:auto 0 0; }.sa-service figure::after { content:""; position:absolute; inset:0; background:linear-gradient(transparent 55%,rgb(0 0 0 / .78)); }.sa-service figure a { width:38px; height:38px; z-index:2; right:12px; bottom:12px; border-radius:50%; background:var(--sa-lime); }.sa-service:hover { border-color:var(--sa-lime); transform:translateY(-7px); }.sa-service:hover figure img { transform:scale(1.06); }
